            ],
            'last_changed' => $now,
            'last_updated' => $now,
            'context' => [
                'id' => uniqid("ctx_"),
                'parent_id' => null,
                'user_id' => null
            ]
        ];
        $this->sendHttpResponse(json_encode($response));
    }


