    // Hilfsfunktion, um einen gültigen Entity-Namen zu erstellen
    private function generateEntityName($name)
    {
        // Konvertiert den Gerätenamen in Kleinbuchstaben und ersetzt Leerzeichen durch Unterstriche
        return strtolower(str_replace(' ', '_', $name));
    }

    private function sendHttpResponse($response)
    {
        // Erstelle den HTTP-Response-Header
        $httpResponse = "HTTP/1.1 200 OK\r\n";
        $httpResponse .= "Content-Type: application/json\r\n";
        $httpResponse .= "Content-Length: " . strlen($response) . "\r\n";
        $httpResponse .= "Connection: close\r\n";
        $httpResponse .= "\r\n";  // Ende der Header
        $httpResponse .= $response;  // JSON-Daten anhängen

        // Lies die ClientIP und den ClientPort aus den Attributen
        $ClientIP = $this->ReadAttributeString('ClientIP');
        $ClientPort = $this->ReadAttributeInteger('ClientPort');

        // Sende die HTTP-Antwort über den Parent (ServerSocket)
        $this->SendDataToParent(json_encode([
            'DataID' => '{C8792760-65CF-4C53-B5C7-A30FCC84FEFE}',  // Standard-ID für die Kommunikation mit Sockets
            'Buffer' => mb_convert_encoding($httpResponse, 'UTF-8', 'ISO-8859-1'),  // HTTP-Antwort als Buffer
            'ClientIP' => $ClientIP,  // IP-Adresse des Clients
            'ClientPort' => $ClientPort  // Port des Clients
        ]));

        // Debug-Ausgabe für die gesendete Antwort
        $this->SendDebug('HaptiqueEmulator', 'Antwort gesendet: ' . $httpResponse, 0);
    }

    private function sendErrorResponse(int $code, string $message): void
    {
        $statusText = match ($code) {
            400 => 'Bad Request',
            401 => 'Unauthorized',
            404 => 'Not Found',
            500 => 'Internal Server Error',
            default => 'Error'
        };

        $body = json_encode(['error' => $message]);

        $httpResponse = "HTTP/1.1 $code $statusText\r\n";
        $httpResponse .= "Content-Type: application/json\r\n";
        $httpResponse .= "Content-Length: " . strlen($body) . "\r\n";
        $httpResponse .= "Connection: close\r\n\r\n";
        $httpResponse .= $body;

        $ClientIP = $this->ReadAttributeString('ClientIP');
        $ClientPort = $this->ReadAttributeInteger('ClientPort');

        $this->SendDataToParent(json_encode([
            'DataID' => '{C8792760-65CF-4C53-B5C7-A30FCC84FEFE}',
            'Buffer' => mb_convert_encoding($httpResponse, 'UTF-8', 'ISO-8859-1'),
            'ClientIP' => $ClientIP,
            'ClientPort' => $ClientPort
        ]));

        $this->SendDebug('HaptiqueEmulator', "Fehler gesendet: $code $statusText – $message", 0);
    }

    public function NewIDLightSwitch($LightSwitches)
    {
        $values = [];
        foreach ($LightSwitches as $target) {
            if ($target['ID'] == 0) {
                $target['ID'] = $this->generateIdentifier();
            }
            $values[] = $target;
        }
        $this->UpdateFormField('LightSwitches', 'values', json_encode($values));
    }

    public function generateIdentifier()
    {
        $newID = $this->ReadAttributeInteger('NewIDLighSwicth');
        $this->WriteAttributeInteger('NewIDLighSwicth', $newID + 1);
        return $newID;
        // return sprintf('{%04X%04X-%04X-%04X-%04X-%04X%04X%04X}', mt_rand(0, 65535), mt_rand(0, 65535), mt_rand(0, 65535), mt_rand(16384, 20479), mt_rand(32768, 49151), mt_rand(0, 65535), mt_rand(0, 65535), mt_rand(0, 65535));

    }

    private function GetSymconFirstName(): string
    {
        $email = @IPS_GetLicensee();
        if (empty($email) || strpos($email, '@') === false) {
            return 'Symcon';
        }
        $username = explode('@', $email)[0];

        // Trenne an Punkt, Unterstrich oder Bindestrich
        $parts = preg_split('/[\._\-]/', $username);

        // Nimm den ersten sinnvollen Teil
        $first = $parts[0] ?? 'Symcon';

        // Großschreibung des ersten Buchstabens
        $first = ucfirst(strtolower($first));

        return $first;
    }

    private function RegisterMdnsService()
    {
        $this->SendDebug(__FUNCTION__, '🔧 DNS-SD Dienst registrieren', 0);

        $mdnsID = @IPS_GetInstanceListByModuleID('{780B2D48-916C-4D59-AD35-5A429B2355A5}')[0] ?? 0;
        if ($mdnsID === 0) {
            $this->SendDebug(__FUNCTION__, '⚠️ Keine DNS-SD Control Instanz gefunden!', 0);
            return;
        }

        $entries = json_decode(IPS_GetProperty($mdnsID, 'Services'), true) ?? [];

        $serviceName = 'Symcon';
        $serviceType = '_cantata-integration._tcp';

        $entries = array_filter($entries, fn($e) => !($e['Name'] === $serviceName && $e['RegType'] === $serviceType)
        );

        $first = $this->GetSymconFirstName();

        $entries[] = [
            'Name' => $serviceName,
            'RegType' => $serviceType,
            'Domain' => '',
            'Host' => '',
            'Port' => self::DEFAULT_WS_PORT,
            'TXTRecords' => [
                ['Value' => 'name=Symcon von ' . $first],
                ['Value' => 'ver=' . self::Haptique_Driver_Version],
                ['Value' => 'developer=Fonzo'],
                ['Value' => 'pwd=true']
            ]
        ];

        IPS_SetProperty($mdnsID, 'Services', json_encode(array_values($entries)));
        IPS_ApplyChanges($mdnsID);

        $this->SendDebug(__FUNCTION__, '✅ mDNS-Eintrag hinzugefügt: ' . json_encode(end($entries)), 0);
    }

    private function UnregisterMdnsService()
    {
        $mdnsID = @IPS_GetInstanceListByModuleID('{780B2D48-916C-4D59-AD35-5A429B2355A5}')[0] ?? 0;
        if ($mdnsID === 0) {
            return;
        }

        $entries = json_decode(IPS_GetProperty($mdnsID, 'Services'), true) ?? [];
        $filtered = array_filter($entries, function ($entry) {
            return $entry['RegType'] !== '_uc-integration._tcp' || $entry['Name'] !== 'Symcon';
        });

        IPS_SetProperty($mdnsID, 'Services', json_encode(array_values($filtered)));
        IPS_ApplyChanges($mdnsID);
    }

